import{_ as e,o as r,c as o,ag as a}from"./chunks/framework.OsDJF_Ea.js";const u=JSON.parse('{"title":"Google Drive 모듈 (기관관리자)","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/modules-gdrive.md","filePath":"04-org-admin-guide/modules-gdrive.md","lastUpdated":1780579853000}'),i={name:"04-org-admin-guide/modules-gdrive.md"};function d(l,t,n,h,s,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="google-drive-모듈-기관관리자" tabindex="-1">Google Drive 모듈 (기관관리자) <a class="header-anchor" href="#google-drive-모듈-기관관리자" aria-label="Permalink to &quot;Google Drive 모듈 (기관관리자)&quot;">​</a></h1><p>기관 구성원이 워크허브 안에서 Google Drive 파일을 첨부 / 권한 자동 부여 / Picker UI 로 선택할 수 있도록 Drive 모듈을 활성화합니다.</p><blockquote><p><strong>파일 본체 복사 없음</strong>: 워크허브는 Drive 파일을 자기 스토리지로 복사하지 않습니다. Drive ID + 미리보기 메타만 보관하고, &quot;열기&quot; 시 Drive <code>webViewLink</code> 로 302 redirect.</p></blockquote><hr><h2 id="_1-사전-조건" tabindex="-1">1. 사전 조건 <a class="header-anchor" href="#_1-사전-조건" aria-label="Permalink to &quot;1. 사전 조건&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>확인 위치</th></tr></thead><tbody><tr><td>Google 모듈 활성화 (Workspace OAuth Client 등록)</td><td><a href="./google-integration.html">구글 드라이브/메일 연동</a> 참고</td></tr><tr><td>GCP 프로젝트에서 <strong>Google Drive API</strong> 활성화</td><td>Google Cloud Console → API 라이브러리</td></tr><tr><td>GCP 프로젝트에서 <strong>Google Picker API</strong> 활성화</td><td>동상</td></tr><tr><td>OAuth 동의 화면 scope 에 <code>drive.file</code> 또는 <code>drive</code> 추가</td><td>동상</td></tr></tbody></table><p>Google 모듈 미등록 시 Drive 모듈 토글은 disabled 상태로 표시됩니다.</p><hr><h2 id="_2-모듈-활성화" tabindex="-1">2. 모듈 활성화 <a class="header-anchor" href="#_2-모듈-활성화" aria-label="Permalink to &quot;2. 모듈 활성화&quot;">​</a></h2><h3 id="_2-1-화면-이동" tabindex="-1">2.1 화면 이동 <a class="header-anchor" href="#_2-1-화면-이동" aria-label="Permalink to &quot;2.1 화면 이동&quot;">​</a></h3><p>좌측 사이드바 → <strong>관리자 → 모듈 관리</strong> (<code>/app/admin/modules</code>) → <strong>&quot;구글 드라이브&quot;</strong> 카드 토글 ON</p><h3 id="_2-2-설정-패널" tabindex="-1">2.2 설정 패널 <a class="header-anchor" href="#_2-2-설정-패널" aria-label="Permalink to &quot;2.2 설정 패널&quot;">​</a></h3><p>토글 ON 후 카드의 <strong>[설정]</strong> 버튼:</p><table tabindex="0"><thead><tr><th>항목</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td><strong>공유 드라이브 ID</strong></td><td>선택</td><td>기관 공유 드라이브를 기본 첨부 대상으로 사용. 비워두면 사용자 마이드라이브 사용</td></tr><tr><td><strong>Google Picker API Key</strong></td><td><strong>필수</strong></td><td>Picker UI 가 브라우저에서 사용 — 미설정 시 첨부 버튼 클릭해도 Picker 안 뜸</td></tr><tr><td><strong>자동 권한 부여</strong> (<code>grant_on_send</code>)</td><td>권장 ON</td><td>첨부 메시지 수신자에게 자동 reader 권한 부여 — Drive 콘솔에서 별도 공유 불필요</td></tr></tbody></table><blockquote><p><strong>공유 드라이브 권장</strong>: 마이드라이브 모드는 사용자 퇴사 시 자료가 사라집니다. 회사 자료 영속성을 위해 공유 드라이브 ID 지정 권장.</p></blockquote><hr><h2 id="_3-google-picker-api-key-발급" tabindex="-1">3. Google Picker API Key 발급 <a class="header-anchor" href="#_3-google-picker-api-key-발급" aria-label="Permalink to &quot;3. Google Picker API Key 발급&quot;">​</a></h2><p>Picker 는 별도의 API Key 가 필요합니다. OAuth Client ID 와는 별개.</p><h3 id="_3-1-gcp-console-→-사용자-인증-정보-→-api-키" tabindex="-1">3.1 GCP Console → 사용자 인증 정보 → API 키 <a class="header-anchor" href="#_3-1-gcp-console-→-사용자-인증-정보-→-api-키" aria-label="Permalink to &quot;3.1 GCP Console → 사용자 인증 정보 → API 키&quot;">​</a></h3><ol><li>좌측 <strong>&quot;클라이언트&quot;</strong> (또는 <strong>&quot;API 및 서비스 → 사용자 인증 정보&quot;</strong>)</li><li>상단 <strong>&quot;+ 사용자 인증 정보 만들기&quot; → &quot;API 키&quot;</strong></li><li>키 자동 생성 → 복사</li></ol><h3 id="_3-2-키-제한-필수-권장" tabindex="-1">3.2 키 제한 (필수 권장) <a class="header-anchor" href="#_3-2-키-제한-필수-권장" aria-label="Permalink to &quot;3.2 키 제한 (필수 권장)&quot;">​</a></h3><p>생성된 키 옆 <strong>[키 제한]</strong> 클릭:</p><table tabindex="0"><thead><tr><th>제한</th><th>값</th></tr></thead><tbody><tr><td><strong>애플리케이션 제한 → HTTP 리퍼러</strong></td><td><code>https://&lt;워크허브 도메인&gt;/*</code> (예: <code>https://workhub.koavio.com/*</code>)</td></tr><tr><td><strong>API 제한 → 선택한 API</strong></td><td>Google Picker API + Google Drive API 만 체크</td></tr></tbody></table><h3 id="_3-3-워크허브에-입력" tabindex="-1">3.3 워크허브에 입력 <a class="header-anchor" href="#_3-3-워크허브에-입력" aria-label="Permalink to &quot;3.3 워크허브에 입력&quot;">​</a></h3><p>Drive 모듈 설정 패널의 <strong>Google Picker API Key</strong> 필드에 입력 후 [저장].</p><blockquote><p>이 키는 frontend 번들에 포함돼 클라이언트로 나갑니다 (Picker 가 브라우저에서 사용). HTTP 리퍼러 제한이 보안 경계가 되므로 반드시 위 제한 설정 필요.</p></blockquote><hr><h2 id="_4-crm-drive-폴더-선택" tabindex="-1">4. CRM Drive 폴더 (선택) <a class="header-anchor" href="#_4-crm-drive-폴더-선택" aria-label="Permalink to &quot;4. CRM Drive 폴더 (선택)&quot;">​</a></h2><p>CRM 모듈을 함께 운영 중이면 명함 이미지 Drive 인박스 폴더를 지정할 수 있습니다.</p><ul><li>위치: <strong>CRM 모듈 설정</strong> (Drive 모듈이 아님)</li><li>lazy create: 폴더가 없으면 첫 사용 시 자동 생성</li><li>자세히: <a href="./modules-crm.html">CRM 모듈 (관리자)</a> 참고</li></ul><hr><h2 id="_5-모듈-비활성화-시-영향" tabindex="-1">5. 모듈 비활성화 시 영향 <a class="header-anchor" href="#_5-모듈-비활성화-시-영향" aria-label="Permalink to &quot;5. 모듈 비활성화 시 영향&quot;">​</a></h2><p>기관관리자가 Drive 모듈 토글 OFF 시:</p><table tabindex="0"><thead><tr><th>항목</th><th>영향</th></tr></thead><tbody><tr><td>메시지 첨부의 <strong>Drive 버튼</strong></td><td>즉시 비활성 (로컬 업로드만 가능)</td></tr><tr><td>CRM 명함 Drive 인박스</td><td>비활성 — 수동 입력 / 사진 직접 업로드로 fallback</td></tr><tr><td>미팅 트랜스크립트 [Drive 에서 가져오기]</td><td>[파일에서 가져오기] (로컬 업로드) 로 자동 전환</td></tr><tr><td><strong>기존 Drive 첨부의 칩</strong></td><td>그대로 유지 — &quot;구글에서 열기&quot; 클릭 시 정상 동작</td></tr><tr><td><strong>기존 <code>gdrive_grants</code> 권한</strong></td><td>그대로 유지 — 회수 작업 안 함</td></tr><tr><td>사용자 OAuth 토큰</td><td>보관됨 (재활성 시 복구)</td></tr><tr><td>MCP 도구 <code>attach_drive_file</code> 등</td><td>모듈 비활성으로 호출 시 403</td></tr></tbody></table><p>Drive 권한을 완전 회수하려면 별도 운영 작업 필요 — Drive 콘솔에서 수동 회수 또는 <code>gdrive_grants</code> 일괄 회수 스크립트 (시스템관리자 영역).</p><hr><h2 id="_6-트러블슈팅" tabindex="-1">6. 트러블슈팅 <a class="header-anchor" href="#_6-트러블슈팅" aria-label="Permalink to &quot;6. 트러블슈팅&quot;">​</a></h2><h3 id="picker-api-key-미설정" tabindex="-1">&quot;Picker API Key 미설정&quot; <a class="header-anchor" href="#picker-api-key-미설정" aria-label="Permalink to &quot;&quot;Picker API Key 미설정&quot;&quot;">​</a></h3><ul><li>Drive 모듈 설정 패널의 Picker API Key 입력란 비어 있음 → 위 3번 절차로 발급 + 입력</li></ul><h3 id="picker-가-no-documents-빈-화면" tabindex="-1">Picker 가 &quot;No documents&quot; / 빈 화면 <a class="header-anchor" href="#picker-가-no-documents-빈-화면" aria-label="Permalink to &quot;Picker 가 &quot;No documents&quot; / 빈 화면&quot;">​</a></h3><ul><li>사용자의 다중 Google 세션 충돌 — 사용자가 시크릿 창에서 재시도 권장</li><li>API Key 의 HTTP 리퍼러 제한이 워크허브 도메인과 불일치</li></ul><h3 id="drive-첨부-후-칩이-빨갛게-표시됨-gdrive-grants-status-error" tabindex="-1">Drive 첨부 후 칩이 빨갛게 표시됨 (<code>gdrive_grants.status = error</code>) <a class="header-anchor" href="#drive-첨부-후-칩이-빨갛게-표시됨-gdrive-grants-status-error" aria-label="Permalink to &quot;Drive 첨부 후 칩이 빨갛게 표시됨 (`gdrive_grants.status = error`)&quot;">​</a></h3><ul><li>사용자가 첨부한 파일의 소유자가 아니라 권한 부여 실패 — 공유 드라이브 사용 권장</li><li>Drive 측 quota 초과 / 파일 삭제됨</li></ul><h3 id="사용자-화면에서-drive-버튼이-안-보임" tabindex="-1">사용자 화면에서 Drive 버튼이 안 보임 <a class="header-anchor" href="#사용자-화면에서-drive-버튼이-안-보임" aria-label="Permalink to &quot;사용자 화면에서 Drive 버튼이 안 보임&quot;">​</a></h3><p>체크:</p><ol><li>Google 모듈 활성 + Drive 모듈 활성 모두 ON</li><li>Picker API Key 등록됨</li><li>사용자가 본인 Drive OAuth 동의 완료</li></ol><hr><h2 id="_7-보안-권장사항" tabindex="-1">7. 보안 권장사항 <a class="header-anchor" href="#_7-보안-권장사항" aria-label="Permalink to &quot;7. 보안 권장사항&quot;">​</a></h2><ul><li><strong>OAuth refresh token</strong> AES-256-GCM 암호화</li><li><strong>자동 권한 부여 (<code>grant_on_send</code>)</strong> — 외부 게스트가 포함된 채널에서는 OFF 권장. ON 인 경우 외부 게스트에게도 read 자동 부여</li><li>Picker API Key 의 HTTP 리퍼러 제한 필수</li><li>모든 자동 권한 부여는 <code>gdrive_grants</code> 테이블에 audit (누가 / 언제 / 어떤 파일 / 누구에게)</li></ul><hr><h2 id="관련-가이드" tabindex="-1">관련 가이드 <a class="header-anchor" href="#관련-가이드" aria-label="Permalink to &quot;관련 가이드&quot;">​</a></h2><ul><li><a href="./google-integration.html">구글 드라이브/메일 연동</a> — Google OAuth Client 등록 (사전 조건)</li><li><a href="./../02-user-guide/gdrive-module.html">Google Drive 모듈 (사용자 가이드)</a> — 사용자 화면 / 첨부 흐름 / Drive 인박스</li><li><a href="./modules-gmail.html">Gmail 모듈 (관리자)</a> — Gmail 첨부 → Drive 저장 흐름</li><li><a href="./modules-crm.html">CRM 모듈 (관리자)</a> — 명함 Drive 폴더 설정</li></ul>',52)])])}const P=e(i,[["render",d]]);export{u as __pageData,P as default};
